# from base import BaseClass
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.base import BaseClass
from taf.ul.trs_e2e_fw.lib.oam.exceptions import ParamNotFoundException
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class Parameters(BaseClass):
    def __init__(self):
        super(Parameters, self).__init__()

    def get_parameter(self, **kwargs):
        """
        Get managed object parameters of current plan
        @param kwargs
            param_path: string, Can be full distname or part of distname
            timeout: int, Timeout in seconds for the operation
            alias: string, Name of the execution context
            str_format: bool, Returns result in scalar string format if True, else dictionary is returned

        @return: string, parameter value

        @raise
            Exception
        """
        param_path = kwargs['param_path']
        timeout = kwargs.get('timeout', 30)
        alias = kwargs.get('alias', 'default')
        str_format = kwargs.get('str_format', True)

        param_name = None
        param_val = None

        # search for get parameter
        param_path = param_path.split(":")
        dist_name = param_path[0]
        param_list = param_path[1:]

        # get the last parameter name from the given dist_name
        dist_name_list = dist_name.split("/")
        full_dist_name = self.get_full_dist_name_path(dist_name=dist_name, final_dist_name=dist_name_list[-1],
                                                      alias=alias)
        list_of_param_dict = self.factory.cu_oam.get_parameters(dist_name=full_dist_name, connection=alias)

        for dict in list_of_param_dict['parameters']:
            param_name, param_val = self._get_parameter_value_from_dict(dict, param_list, alias)
            if param_name and param_val:
                break
        else:
            raise ParamNotFoundException("Parameter {} not found".format(param_list))
        return param_val

    def get_full_dist_name_path(self, dist_name, final_dist_name, alias):
        """
        Get dull dist_name
        @param dist_name: string, user given dist_name
        @param final_dist_name: string, last parameter name from the given distname. This is required to form full name
        @param alias: string, name of execution context

        @return: string, full dist_name

        @raise
            Exception
        """
        fetched_dist_name = ''
        if dist_name == '' or dist_name.startswith('MRBTS-'):
            return dist_name
        cur_plan_tree = self.factory.cu_oam.get_current_plan_tree_diff(connection=alias)['created']

        dist_name = dist_name.strip('/')

        param_d = next(filter(lambda d: d.get("name") == dist_name, cur_plan_tree))

        bts_dict = next(filter(lambda d: d.get("parent_mo_uuid") == None, cur_plan_tree))
        bts_mo_uuid = bts_dict.get('mo_uuid')
        bts_name = bts_dict.get('name')

        parent_mo_uuid = ""
        full_path = dist_name
        while parent_mo_uuid != bts_mo_uuid:
            param_d = next(filter(lambda d: d.get("mo_uuid") == param_d.get('parent_mo_uuid'), cur_plan_tree))
            full_path = param_d['name']+'/'+full_path
            parent_mo_uuid = param_d['parent_mo_uuid']

        return bts_name+"/"+full_path


    def _get_parameter_value_from_dict(self, dict_item, param_val_list, alias):
        if isinstance(dict_item, dict):
            param_type = dict_item['parameter_type']
            if param_type == 'simple':
                if dict_item['simple_parameter']['name'] == param_val_list[0]:
                    logger.debug("Parameter list :: {} \n parameter value :: {}".format(
                        param_val_list[0], dict_item['simple_parameter']['value']))
                    return self._get_parameter_value_from_dicts(
                        dict_item['simple_parameter']['name'],
                        dict_item['simple_parameter']['value'],
                        param_val_list[1:], alias)
            elif param_type == 'complex':
                if dict_item['complex_parameter']['name'] == param_val_list[0]:
                    logger.debug("Parameter list :: {} \n parameter value :: {}".format(
                        param_val_list[1:], dict_item['complex_parameter']['value']))
                    return self._get_parameter_value_from_dicts(
                        dict_item['complex_parameter']['name'],
                        dict_item['complex_parameter']['value'],
                        param_val_list[1:], alias)
            return None, None
        else:
            param_type = dict_item['parameter_type']
            if param_type == 'simple':
                if dict_item['simple_parameter']['name'] == param_val_list[0]:
                    logger.debug("Parameter list :: {} \n parameter value :: {}".format(
                        param_val_list[0], dict_item['simple_parameter']['value']))
                    return self._verify_parameter_value(
                        dict_item['simple_parameter']['name'],
                        dict_item['simple_parameter']['value'],
                        param_val_list[1:], alias)
            elif param_type == 'complex':
                if dict_item['complex_parameter']['name'] == param_val_list[0]:
                    logger.debug("Parameter list :: {} \n parameter value :: {}".format(
                        param_val_list[1:], dict_item['complex_parameter']['value']))
                    return self._verify_parameter_value(
                        dict_item['complex_parameter']['name'],
                        dict_item['complex_parameter']['value'],
                        param_val_list[1:], alias)
            return None, None

    def _get_parameter_value_from_dicts(self, resp_name, resp_val, param_list, alias):
        if not isinstance(resp_val, list):
            return self._verify_parameter_value(resp_name, resp_val, param_list, alias)
            # return resp_val
        for each_item in resp_val:
            for struct_dic in each_item.structure_parameters:
                resp_name, resp_val = self._get_parameter_value_from_dict(struct_dic, param_list, alias)
                if resp_name and resp_val:
                    return resp_name, resp_val
                    # return resp_name, resp_val

    def _verify_parameter_value(self, resp_name, resp_val, param_list, alias):
        if 'MRBTS-' in resp_val:
            list_of_param_dict = self.factory.cu_oam.get_parameters(dist_name=resp_val, connection=alias)
            for dict in list_of_param_dict['parameters']:
                return self._get_parameter_value_from_dict(dict, param_list, alias)
        return resp_name, resp_val
